// Classifies each WhatsApp webhook event into a route for the Switch.
// Keyword routes run before the AI so they are instant and deterministic.
const HANDOFF_MS = 12 * 60 * 60 * 1000;
const state = $getWorkflowStaticData('global');
state.handoff = state.handoff || {};
const now = Date.now();
const out = [];

for (const item of $input.all()) {
  const j = item.json;

  if (Array.isArray(j.statuses) && j.statuses.length) {
    const s = j.statuses[0];
    out.push({ json: { route: 'status', from: s.recipient_id, status: s.status, messageId: s.id, errors: s.errors || [] } });
    continue;
  }

  const msg = Array.isArray(j.messages) ? j.messages[0] : undefined;
  if (!msg) continue;

  const from = msg.from;
  const name = (j.contacts && j.contacts[0] && j.contacts[0].profile && j.contacts[0].profile.name) || '';
  const text = (
    (msg.text && msg.text.body) ||
    (msg.button && msg.button.text) ||
    (msg.interactive && msg.interactive.button_reply && msg.interactive.button_reply.title) ||
    ''
  ).trim();
  const lower = text.toLowerCase();
  const base = { from, name, text, messageId: msg.id, type: msg.type };

  const until = state.handoff[from] || 0;
  if (/^\s*(bot|volver al bot)\s*$/i.test(text)) {
    delete state.handoff[from];
    out.push({ json: { ...base, route: 'ia', text: 'Hola' } });
    continue;
  }
  if (until > now) {
    out.push({ json: { ...base, route: 'silenciado' } });
    continue;
  }

  if (!text) {
    out.push({ json: { ...base, route: 'no_texto' } });
    continue;
  }
  if (/^\s*(baja|stop|parar|no mas promociones|no más promociones)\s*[.!]*\s*$/i.test(lower)) {
    out.push({ json: { ...base, route: 'baja' } });
    continue;
  }
  if (/(asesor|humano|persona real|hablar con (alguien|una persona|un agente|alguien del equipo)|agente|atenci[oó]n personal)/i.test(lower)) {
    state.handoff[from] = now + HANDOFF_MS;
    out.push({ json: { ...base, route: 'humano', handoffUntil: new Date(now + HANDOFF_MS).toISOString() } });
    continue;
  }
  const code = text.match(/\bAT[-\s]?(\d{1,6})\b/i) || text.match(/\bticket\D{0,12}(\d{1,6})\b/i);
  if (code) {
    out.push({ json: { ...base, route: 'ticket', codigo: code[1] } });
    continue;
  }
  out.push({ json: { ...base, route: 'ia' } });
}

return out;

// Looks the ticket up by code + the sender's WhatsApp number (same check as the public page).
const ESTADOS = {
  pendiente: 'recibido y pendiente de revisión',
  aprobado: 'aprobado, en cola para reparación',
  trabajando: 'en reparación ahora mismo',
  listo: '¡listo para recoger! 🎉',
  entregado: 'entregado',
  cancelado: 'cancelado',
  abandonado: 'cerrado por falta de recojo',
};
const out = [];
for (const item of $input.all()) {
  const { from, codigo } = item.json;
  let reply;
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.armalytech.com/api/tickets/public/lookup',
      body: { codigo, telefono: from },
      json: true,
      timeout: 8000,
    });
    // The API wraps payloads as { ok, data }.
    const found = res.data || res;
    const t = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.armalytech.com/api/tickets/public/' + encodeURIComponent(found.publicToken),
      json: true,
      timeout: 8000,
    });
    const data = t.data || t;
    const equipo = [data.equipo && data.equipo.marca, data.equipo && data.equipo.modelo].filter(Boolean).join(' ');
    const estado = ESTADOS[data.estado] || data.estado;
    reply = 'Tu ticket ' + data.codigo + (equipo ? ' (' + equipo + ')' : '') + ' está ' + estado + '.';
    if (data.estado === 'listo' && data.saldo > 0) reply += ' Saldo pendiente: S/ ' + Number(data.saldo).toFixed(2) + '.';
    reply += '\nDetalle: https://demo.armalytech.com/ticket/' + found.publicToken;
  } catch (e) {
    reply = 'No encontré un ticket con ese número para este WhatsApp. Revisa el código (ej. AT-000123) o escribe "asesor" y te ayuda una persona del equipo.';
  }
  out.push({ json: { ...item.json, reply } });
}
return out;
